<div class="container">
    <header>
        <button class="print-btn" onclick="window.print()">Print Final Plan</button>
        <h1>Apartment Chore Draft Board</h1>
        <div class="subtitle">Add options, take turns drafting, and lock in the weekly schedule.</div>
        <div class="clear"></div>
    </header>

    <div class="setup-actions">
        <div class="input-group">
            <label for="roommate-input">Roommate:</label>
            <input type="text" id="roommate-input" placeholder="e.g., Alex" onkeydown="if(event.key==='Enter') addRoommate()">
