                </div>
        </div>

        <div class="pool-block" id="chores-pool-wrapper">
            <div class="pool-title">Available Chores Pool (Click to clear from pool if drafted manually)</div>
            <div id="chores-pool" class="pill-container">
                </div>
        </div>
    </div>

    <div class="draft-mechanism">
        <strong style="font-size: 10pt; color: #2c3e50; margin-right: 10px;">Draft Turn:</strong>
        <select id="select-roommate">
            <option value="">-- Select Roommate --</option>
        </select>
        <select id="select-chore">
            <option value="">-- Select Chore --</option>
        </select>
        <button onclick="assignChore()">Confirm Selection</button>
    </div>

    <div class="board-title">Weekly Assignments</div>

    <table class="grid-table">
        <thead>
            <tr id="table-headers">
                <th style="color: #cbd5e1; font-style: italic; font-weight: normal;">No roommates added yet.</th>
            </tr>
        </thead>
        <tbody>
            <tr id="table-columns">
                <td style="color: #94a3b8; font-style: italic;">Add roommates above to initialize the draft board columns.</td>
            </tr>
        </tbody>
    </table>
</div>

<script>
    // State management
    let roommates = [];
    let chores = [];
    let assignments = {}; // Structure: { roommateName: [chore1, chore2] }

    function updateUI() {
        // 1. Update Roommates Pool View
        const rmPool = document.getElementById('roommates-pool');
        rmPool.innerHTML = roommates.length === 0 ? '<span style="color:#94a3b8; font-style:italic; font-size:9pt;">No roommates added yet.</span>' : '';
        roommates.forEach(rm => {
            const span = document.createElement('span');
            span.className = 'pill';
            span.textContent = rm;
            rmPool.appendChild(span);
        });

        // 2. Update Chores Pool View
        const chorePool = document.getElementById('chores-pool');
        chorePool.innerHTML = chores.length === 0 ? '<span style="color:#94a3b8; font-style:italic; font-size:9pt;">No available chores remaining.</span>' : '';
        chores.forEach((chore, index) => {
            const span = document.createElement('span');
            span.className = 'pill chore-pill';
            span.innerHTML = `${chore} <span style="font-size:7pt; margin-left:4px; opacity:0.6;">&times;</span>`;
            span.onclick = () => removeChoreFromPool(index);
            chorePool.appendChild(span);
        });

        // 3. Update Dropdown selectors
        const rmSelect = document.getElementById('select-roommate');
        const currentRmSel = rmSelect.value;
        rmSelect.innerHTML = '<option value="">-- Select Roommate --</option>';
        roommates.forEach(rm => {
            const opt = document.createElement('option');
            opt.value = rm;
            opt.textContent = rm;
            if (rm === currentRmSel) opt.selected = true;
            rmSelect.appendChild(opt);
        });

        const choreSelect = document.getElementById('select-chore');
        choreSelect.innerHTML = '<option value="">-- Select Chore --</option>';
        chores.forEach(chore => {
            const opt = document.createElement('option');
            opt.value = chore;
            opt.textContent = chore;
            choreSelect.appendChild(opt);
        });

        // 4. Update Board Matrix Grid (Table Columns)
        const tHeaders = document.getElementById('table-headers');
        const tColumns = document.getElementById('table-columns');

        if (roommates.length === 0) {
            tHeaders.innerHTML = '<th style="color: #cbd5e1; font-style: italic; font-weight: normal;">No roommates added yet.</th>';
            tColumns.innerHTML = '<td style="color: #94a3b8; font-style: italic;">Add roommates above to initialize the draft board columns.</td>';
            return;
        }

        tHeaders.innerHTML = '';
        tColumns.innerHTML = '';

        roommates.forEach(rm => {
            // Header cell
            const th = document.createElement('th');
            th.textContent = rm;
            tHeaders.appendChild(th);

            // Data cell matching roommate
            const td = document.createElement('td');
            const rmChores = assignments[rm] || [];

            if (rmChores.length === 0) {
                td.innerHTML = '<div style="color: #cbd5e1; font-style: italic; font-size: 9pt; padding: 5px 0;">No chores drafted</div>';
            } else {
                rmChores.forEach((chore, cIdx) => {
                    const cDiv = document.createElement('div');
                    cDiv.className = 'assigned-chore';

                    const removeBtn = document.createElement('span');
                    removeBtn.className = 'remove-assignment';
                    removeBtn.innerHTML = '&times;';
                    removeBtn.onclick = () => unassignChore(rm, cIdx);

                    cDiv.appendChild(removeBtn);
                    cDiv.appendChild(document.createTextNode(chore));
                    td.appendChild(cDiv);
                });
            }
            tColumns.appendChild(td);
        });
    }

    function addRoommate() {
        const input = document.getElementById('roommate-input');
        const val = input.value.trim();
        if (val && !roommates.includes(val)) {
            roommates.push(val);
            if (!assignments[val]) assignments[val] = [];
            input.value = '';
            updateUI();
        }
    }

    function addChore() {
        const input = document.getElementById('chore-input');
        const val = input.value.trim();
        if (val && !chores.includes(val)) {
            chores.push(val);
            input.value = '';
            updateUI();
        }
    }

    function removeChoreFromPool(index) {
        chores.splice(index, 1);
        updateUI();
    }

    function assignChore() {
        const rm = document.getElementById('select-roommate').value;
        const chore = document.getElementById('select-chore').value;

        if (!rm || !chore) return;

        // Add to assigned track
        assignments[rm].push(chore);

        // Pluck from available pool
        const cIndex = chores.indexOf(chore);
        if (cIndex > -1) chores.splice(cIndex, 1);

        updateUI();
    }

    function unassignChore(roommate, index) {
        const returnedChore = assignments[roommate][index];
        assignments[roommate].splice(index, 1);
        chores.push(returnedChore);
        updateUI();
    }

    // Initialize with standard sample values for immediate quick testing
    window.onload = function() {
        roommates = ["Roommate 1", "Roommate 2", "Roommate 3"];
        chores = ["Kitchen Counters & Sink", "Bathroom Deep Clean", "Living Room Vacuuming", "Trash & Recycling", "Mop Hardwood Floors"];
        roommates.forEach(rm => assignments[rm] = []);
        updateUI();
    };
</script>

</body>
</html>
