<script>
    // System Core State
    let roommates = ["Roommate 1", "Roommate 2", "Roommate 3"];
    let chores = ["Kitchen Counters & Sink", "Bathroom Deep Clean", "Living Room Vacuuming", "Trash & Recycling", "Mop Hardwood Floors", "Wipe Windows & Dust"];
    let assignments = {};

    let draftActive = false;
    let currentTurnIndex = 0; // Absolute track marker across entire snake chain
    let snakeOrderQueue = []; // Precalculated sequence of picker names

    function buildSnakeQueue() {
        if (roommates.length === 0 || chores.length === 0) return [];

        let roundsNeeded = Math.ceil(chores.length / roommates.length);
        let order = [];

        for (let r = 0; r < roundsNeeded; r++) {
            // Forward order on even rounds (0, 2, 4), Reversed order on odd rounds (1, 3, 5)
            if (r % 2 === 0) {
                for (let i = 0; i < roommates.length; i++) {
                    order.push({ name: roommates[i], round: r + 1, direction: 'Forward' });
                }
            } else {
                for (let i = roommates.length - 1; i >= 0; i--) {
                    order.push({ name: roommates[i], round: r + 1, direction: 'Reverse' });
                }
            }
        }
        return order;
    }

    function initMatrixLayout() {
        const tHeaders = document.getElementById('table-headers');
        const tColumns = document.getElementById('table-columns');

        tHeaders.innerHTML = '';
        tColumns.innerHTML = '';

        if(roommates.length === 0) {
            tHeaders.innerHTML = '<th style="color: #cbd5e1; font-weight: normal; font-style: italic;">No Roommates</th>';
            tColumns.innerHTML = '<td style="color: #94a3b8; font-style: italic;">Add roommates to build columns.</td>';
            return;
        }

        roommates.forEach(rm => {
            if(!assignments[rm]) assignments[rm] = [];

            const th = document.createElement('th');
            th.textContent = rm;
            tHeaders.appendChild(th);

            const td = document.createElement('td');
            td.id = `col-${btoa(rm).replace(/=/g, '')}`; // Safe ID mapping
            tColumns.appendChild(td);
        });
    }

    function renderMatrixData() {
        roommates.forEach(rm => {
            const td = document.getElementById(`col-${btoa(rm).replace(/=/g, '')}`);
            if (!td) return;

            td.innerHTML = '';
            const list = assignments[rm] || [];

            if(list.length === 0) {
                td.innerHTML = '<div style="color: #cbd5e1; font-style: italic; font-size: 9pt; padding: 4px 0;">No chores drafted</div>';
            } else {
                list.forEach((chore, idx) => {
                    const div = document.createElement('div');
                    div.className = 'assigned-chore';

                    const txt = document.createElement('span');
                    txt.textContent = chore;

                    const del = document.createElement('span');
                    del.className = 'remove-assignment';
                    del.innerHTML = '&times;';
                    del.onclick = () => dropChoreAssignment(rm, idx, chore);

                    div.appendChild(txt);
                    div.appendChild(del);
                    td.appendChild(div);
                });
            }
        });
    }

    function renderDraftEngine() {
        const poolContainer = document.getElementById('chores-pool');
        poolContainer.innerHTML = '';

        // Render remaining chores in pool
        if (chores.length === 0) {
            poolContainer.innerHTML = '<span style="color:#94a3b8; font-style:italic; font-size:9.5pt; padding: 5px 0;">All tasks successfully drafted! Board is complete.</span>';
        } else {
            chores.forEach((chore, index) => {
                const span = document.createElement('span');
                span.className = 'chore-pill';
                span.textContent = chore;
                if (draftActive) {
                    span.onclick = () => executeDraftPick(chore, index);
                } else {
                    span.innerHTML += ` <span style="font-size:7.5pt; color:#ef4444; margin-left:4px;" onclick="event.stopPropagation(); removeChoreSetup(${index})">&times;</span>`;
                }
                poolContainer.appendChild(span);
            });
        }

        if (!draftActive) return;

        // Render queue track line
        const queueTrack = document.getElementById('queue-track');
        queueTrack.innerHTML = '';

        if (currentTurnIndex >= snakeOrderQueue.length || chores.length === 0) {
            document.getElementById('active-picker').textContent = "Draft Complete";
            document.getElementById('direction-tag').textContent = "Done";
            return;
        }

        const currentTurn = snakeOrderQueue[currentTurnIndex];
        document.getElementById('active-picker').textContent = currentTurn.name;
        document.getElementById('direction-tag').textContent = `Round ${currentTurn.round} (${currentTurn.direction})`;

        // Render visible horizontal queue ribbon for next choices
        let sliceStart = currentTurnIndex;
        let sliceEnd = Math.min(currentTurnIndex + 6, snakeOrderQueue.length);

        for (let i = sliceStart; i < sliceEnd; i++) {
            if (i > sliceStart) {
                const arrow = document.createElement('span');
                arrow.className = 'queue-arrow';
                arrow.innerHTML = '&#10142;';
                queueTrack.appendChild(arrow);
            }
            const qItem = document.createElement('div');
            qItem.className = `queue-item ${i === currentTurnIndex ? 'active' : ''}`;
            qItem.textContent = `${snakeOrderQueue[i].name} (R${snakeOrderQueue[i].round})`;
            queueTrack.appendChild(qItem);
        }
    }

    function addRoommate() {
        if(draftActive) return;
        const input = document.getElementById('roommate-input');
        const val = input.value.trim();
        if (val && !roommates.includes(val)) {
            roommates.push(val);
            input.value = '';
            initMatrixLayout();
            renderDraftEngine();
        }
    }

    function addChore() {
        const input = document.getElementById('chore-input');
        const val = input.value.trim();
        if (val && !chores.includes(val)) {
            chores.push(val);
            input.value = '';
            renderDraftEngine();
        }
    }

    function removeChoreSetup(idx) {
        if(draftActive) return;
        chores.splice(idx, 1);
        renderDraftEngine();
    }

    function startDraft() {
        if (roommates.length === 0 || chores.length === 0) return;
        draftActive = true;
        snakeOrderQueue = buildSnakeQueue();
        currentTurnIndex = 0;

        document.getElementById('setup-panel').style.display = 'none';
        document.getElementById('draft-panel').style.display = 'block';
        document.getElementById('pool-title-text').textContent = "Available Chores Pool (Click a item below to choose it for the active roommate)";

        renderDraftEngine();
    }

    function executeDraftPick(chore, poolIdx) {
        if (!draftActive || currentTurnIndex >= snakeOrderQueue.length) return;

        const currentPicker = snakeOrderQueue[currentTurnIndex].name;

        // Push to matrix state
        assignments[currentPicker].push(chore);
        // Remove from available pool 
        chores.splice(poolIdx, 1);

        // Step engine forward
        currentTurnIndex++;

        renderMatrixData();
        renderDraftEngine();
    }

    function dropChoreAssignment(roommate, choreIdx, choreName) {
        assignments[roommate].splice(choreIdx, 1);
        chores.push(choreName);

        // If the draft is actively going, re-calculate queue steps safely
        if (draftActive) {
            snakeOrderQueue = buildSnakeQueue();
            // Roll step counter back exactly one step if they are fixing an immediate blunder
            if (currentTurnIndex > 0) {
                currentTurnIndex--;
            }
        }

        renderMatrixData();
        renderDraftEngine();
    }

    window.onload = function() {
        initMatrixLayout();
        renderDraftEngine();
        renderMatrixData();
    };
</script>

</body>
</html>
