<script>
    // App Core Configurations 
    let roommates = ["Alex", "Taylor", "Jordan"];
    let chores = [
        { name: "Deep Clean Bathroom", weight: 5 },
        { name: "Mop Common Room Floors", weight: 4 },
        { name: "Wipe Down Kitchen Counters", weight: 3 },
        { name: "Load/Empty Dishwasher", weight: 2 },
        { name: "Take Out Trash & Recycling", weight: 1 }
    ];
    let assignments = {};

    let draftActive = false;
    let currentTurnIndex = 0; 
    let snakeOrderQueue = []; 

    function saveState() {
        const payload = { roommates, chores, assignments, draftActive, currentTurnIndex, snakeOrderQueue };
        localStorage.setItem('apt_balanced_chore_state', JSON.stringify(payload));

        const now = new Date();
        document.getElementById('save-status').textContent = `Autosaved at ${now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}`;
    }

    function loadState() {
        const data = localStorage.getItem('apt_balanced_chore_state');
        if (data) {
            try {
                const parsed = JSON.parse(data);
                roommates = parsed.roommates || [];
                chores = parsed.chores || [];
                assignments = parsed.assignments || {};
                draftActive = !!parsed.draftActive;
                currentTurnIndex = parsed.currentTurnIndex || 0;
                snakeOrderQueue = parsed.snakeOrderQueue || [];
                document.getElementById('save-status').textContent = "State loaded from browser storage";
                return true;
            } catch(e) {
                console.error(e);
            }
        }
        return false;
    }

    function resetBoard() {
        if (confirm("Reset everything and return to step-one setup configuration?")) {
            localStorage.removeItem('apt_balanced_chore_state');
            roommates = ["Alex", "Taylor", "Jordan"];
            chores = [
                { name: "Deep Clean Bathroom", weight: 5 },
                { name: "Mop Common Room Floors", weight: 4 },
                { name: "Wipe Down Kitchen Counters", weight: 3 },
                { name: "Load/Empty Dishwasher", weight: 2 },
                { name: "Take Out Trash & Recycling", weight: 1 }
            ];
            assignments = {};
            draftActive = false;
            currentTurnIndex = 0;
            snakeOrderQueue = [];

            document.getElementById('setup-panel').style.display = 'block';
            document.getElementById('draft-panel').style.display = 'none';
            document.getElementById('finish-banner').style.display = 'none';
            document.getElementById('pool-title-text').textContent = "Available Chores Pool";

            initMatrixStructure();
            renderEngineUI();
            document.getElementById('save-status').textContent = "Board completely reset";
        }
    }

    function buildSnakeStructure() {
        if (roommates.length === 0 || chores.length === 0) return [];
        let totalTaskCount = chores.length + Object.values(assignments).flat().length;
        let roundsNeeded = Math.ceil(totalTaskCount / roommates.length);
        let queue = [];

        for (let r = 0; r < roundsNeeded; r++) {
            if (r % 2 === 0) {
                for (let i = 0; i < roommates.length; i++) {
                    queue.push({ name: roommates[i], round: r + 1, direction: 'Forward' });
                }
            } else {
                for (let i = roommates.length - 1; i >= 0; i--) {
                    queue.push({ name: roommates[i], round: r + 1, direction: 'Reverse' });
                }
            }
        }
        return queue;
    }

    function initMatrixStructure() {
        const tHeaders = document.getElementById('table-headers');
        const tColumns = document.getElementById('table-columns');
        tHeaders.innerHTML = ''; tColumns.innerHTML = '';

        if (roommates.length === 0) {
            tHeaders.innerHTML = '<th style="color:#cbd5e1; font-weight:normal; font-style:italic;">No roommates added yet</th>';
            tColumns.innerHTML = '<td style="color:#94a3b8; font-style:italic;">Columns will populate when names are entered above.</td>';
            return;
        }

        let widthPct = (100 / roommates.length).toFixed(2) + '%';
        roommates.forEach(rm => {
            if (!assignments[rm]) assignments[rm] = [];

            const th = document.createElement('th');
            th.style.width = widthPct;
            th.innerHTML = `${rm} <span class="load-indicator" id="load-label-${btoa(rm).replace(/=/g,'')}">Total Effort: 0 pts</span>`;
            tHeaders.appendChild(th);

            const td = document.createElement('td');
            td.id = `box-${btoa(rm).replace(/=/g, '')}`;
            td.style.width = widthPct;
            tColumns.appendChild(td);
        });
        calculateWorkloads();
    }

    function calculateWorkloads() {
        let totalAssignedPoints = 0;
        roommates.forEach(rm => {
            const list = assignments[rm] || [];
            let sum = 0;
            list.forEach(item => sum += item.weight);
            totalAssignedPoints += sum;

            const lbl = document.getElementById(`load-label-${btoa(rm).replace(/=/g,'')}`);
            if (lbl) lbl.textContent = `Total Effort: ${sum} pt${sum !== 1 ? 's' : ''}`;

            const box = document.getElementById(`box-${btoa(rm).replace(/=/g, '')}`);
            if (!box) return;
            box.innerHTML = '';

            if (list.length === 0) {
                box.innerHTML = '<div style="color: #cbd5e1; font-style: italic; font-size: 9pt; padding: 4px 0;">No items drafted</div>';
            } else {
                list.forEach((chore, index) => {
                    const div = document.createElement('div');
                    div.className = 'assigned-chore';
                    div.innerHTML = `<span>${chore.name} <span class="effort-badge">${chore.weight}</span></span>`;

                    const del = document.createElement('span');
                    del.className = 'remove-assignment';
                    del.innerHTML = '&times;';
                    del.onclick = () => dropAssignmentItem(rm, index, chore);

                    div.appendChild(del);
                    box.appendChild(div);
                });
            }
        });

        // Toggle CSS banner if draft is complete
        if (draftActive && chores.length === 0 && totalAssignedPoints > 0) {
            document.getElementById('finish-banner').style.display = 'block';
        } else {
            document.getElementById('finish-banner').style.display = 'none';
        }
    }

    function renderEngineUI() {
        const pool = document.getElementById('chores-pool');
        pool.innerHTML = '';

        if (chores.length === 0) {
            pool.innerHTML = '<span style="color:#94a3b8; font-style:italic; font-size:9.5pt; padding:4px 0;">All items have been allocated.</span>';
        } else {
            chores.forEach((chore, index) => {
                const span = document.createElement('span');
                span.className = 'chore-pill';
                span.innerHTML = `${chore.name} <span class="effort-badge">${chore.weight} pts</span>`;
                if (draftActive) {
                    span.onclick = () => chooseChore(chore, index);
                } else {
                    span.innerHTML += `<span style="font-size:8pt; color:#ef4444; font-weight:bold; cursor:pointer;" onclick="event.stopPropagation(); deleteSetupChore(${index})">&times;</span>`;
                }
                pool.appendChild(span);
            });
        }

        if (!draftActive) return;

        const container = document.getElementById('queue-track');
        container.innerHTML = '';

        if (currentTurnIndex >= snakeOrderQueue.length || chores.length === 0) {
            document.getElementById('active-picker').textContent = "Draft Complete";
            document.getElementById('direction-tag').textContent = "Finished";
            return;
        }

        const currentTurn = snakeOrderQueue[currentTurnIndex];
        document.getElementById('active-picker').textContent = currentTurn.name;
        document.getElementById('direction-tag').textContent = `Round ${currentTurn.round} (${currentTurn.direction})`;

        let endIdx = Math.min(currentTurnIndex + 5, snakeOrderQueue.length);
        for (let i = currentTurnIndex; i < endIdx; i++) {
            if (i > currentTurnIndex) {
                const arrow = document.createElement('span');
                arrow.className = 'queue-arrow';
                arrow.innerHTML = '&#10142;';
                container.appendChild(arrow);
            }
            const node = document.createElement('div');
            node.className = `queue-item ${i === currentTurnIndex ? 'active' : ''}`;
            node.textContent = `${snakeOrderQueue[i].name} (R${snakeOrderQueue[i].round})`;
            container.appendChild(node);
        }
    }

    function addRoommate() {
        if (draftActive) return;
        const input = document.getElementById('roommate-input');
        const val = input.value.trim();
        if (val && !roommates.includes(val)) {
            roommates.push(val);
            input.value = '';
            initMatrixStructure();
            renderEngineUI();
            saveState();
        }
    }

    function addChore() {
        const input = document.getElementById('chore-input');
        const weightSelect = document.getElementById('chore-weight');
        const val = input.value.trim();
        if (val) {
            chores.push({ name: val, weight: parseInt(weightSelect.value) });
            input.value = '';
            renderEngineUI();
            saveState();
        }
    }

    function deleteSetupChore(index) {
        if (draftActive) return;
        chores.splice(index, 1);
        renderEngineUI();
        saveState();
    }

    function startDraft() {
        if (roommates.length === 0 || chores.length === 0) return;
        draftActive = true;
        snakeOrderQueue = buildSnakeStructure();
        currentTurnIndex = 0;

        document.getElementById('setup-panel').style.display = 'none';
        document.getElementById('draft-panel').style.display = 'block';
        document.getElementById('pool-title-text').textContent = "Available Pool Chores (Click item to choose)";

        renderEngineUI();
        calculateWorkloads();
        saveState();
    }

    function chooseChore(chore, index) {
        if (!draftActive || currentTurnIndex >= snakeOrderQueue.length) return;

        const activeUser = snakeOrderQueue[currentTurnIndex].name;
        assignments[activeUser].push(chore);
        chores.splice(index, 1);
        currentTurnIndex++;

        calculateWorkloads();
        renderEngineUI();
        saveState();
    }

    function dropAssignmentItem(user, index, chore) {
        assignments[user].splice(index, 1);
        chores.push(chore);

        if (draftActive) {
            snakeOrderQueue = buildSnakeStructure();
            if (currentTurnIndex > 0) currentTurnIndex--;
        }

        calculateWorkloads();
        renderEngineUI();
        saveState();
    }

    function showToast(msg) {
        const box = document.getElementById('toast-alert');
        box.textContent = msg;
        box.classList.add('visible');
        setTimeout(() => box.classList.remove('visible'), 2800);
    }

    function shareSummary() {
        let text = `🧹 WEEKLY APARTMENT CHORE SHEET 🧹\n\n`;
        roommates.forEach(rm => {
            const list = assignments[rm] || [];
            let total = 0;
            list.forEach(c => total += c.weight);

            text += `👤 ${rm.toUpperCase()} (Total Effort: ${total} pts)\n`;
            if (list.length === 0) {
                text += `  - No chores drafted\n`;
            } else {
                list.forEach(c => {
                    text += `  ▪ ${c.name} [Effort Value: ${c.weight}]\n`;
                });
            }
            text += `\n`;
        });

        if (chores.length > 0) {
            text += `⏳ UNASSIGNED POOL:\n`;
            chores.forEach(c => text += `  ▪ ${c.name} (${c.weight} pts)\n`);
        }

        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(() => showToast("Summary text copied to clipboard!"))
                                              .catch(() => showToast("Failed to write to clipboard."));
        } else {
            showToast("Clipboard unavailable in this context.");
        }
    }

    window.onload = function() {
        loadState();
        initMatrixStructure();
        if (draftActive) {
            document.getElementById('setup-panel').style.display = 'none';
            document.getElementById('draft-panel').style.display = 'block';
            document.getElementById('pool-title-text').textContent = "Available Pool Chores (Click item to choose)";
        }
        renderEngineUI();
    };
</script>

</body>
</html>

